begin;
do $$declare a uuid;c uuid:=gen_random_uuid();p uuid:=gen_random_uuid();u uuid:=gen_random_uuid();m uuid:=gen_random_uuid();g uuid:=gen_random_uuid();l uuid:=gen_random_uuid();d jsonb:='{"title":"QA commissioning basics","objective":"QA practice recorded commissioning procedure","facilitator":"","outcome":"","participants":"","status":"Draft","evidence":"","completed_on":""}';reviewed jsonb;n integer:=0;begin
 select id into a from public.profiles where active and role='admin' order by id limit 1;if a is null then raise exception 'Administrator required';end if;
 perform set_config('request.jwt.claim.sub',a::text,true);perform set_config('request.jwt.claim.role','authenticated',true);
 insert into public.companies(id,name) values(c,'QA training register company');insert into public.projects(id,company_id,title) values(p,c,'QA training register project');
 insert into auth.users(id) values(u),(m);insert into public.profiles(id,name,role,company_id) values(u,'QA training client','client',c);insert into public.profiles(id,name,role) values(m,'QA training manager','team');insert into public.crm_teams(id,name) values(g,'QA training register team');insert into public.crm_memberships(user_id,role_id,team_id) values(m,'project_manager',g);insert into public.project_assignments(project_id,technician_id) values(p,m);
 perform set_config('request.jwt.claim.sub',m::text,true);execute 'set local role authenticated';perform public.save_project_training(l,null,p,d,'QA observed training');if not exists(select 1 from public.crm_project_training where id=l and version=1 and created_by=m) then raise exception 'Draft mismatch';end if;n:=n+1;
 perform public.save_project_training(l,null,p,d,'QA observed training');if (select count(*) from public.crm_project_training_history where training_id=l)<>1 then raise exception 'Retry duplicate';end if;n:=n+1;
 begin perform public.save_project_training(l,null,p,d||'{"title":"QA changed training"}','QA observed training');raise exception 'Changed retry allowed';exception when others then if sqlerrm is distinct from 'Training ID already used with different data' then raise;end if;end;n:=n+1;
 begin perform public.save_project_training(gen_random_uuid(),null,p,d||'{"completed_on":"9999-12-31"}','QA future completion');raise exception 'Future date allowed';exception when others then if sqlerrm is distinct from 'Valid nonfuture completion date required' then raise;end if;end;n:=n+1;
 reviewed:=d||'{"facilitator":"QA trainer","evidence":"QA attendance sheet","completed_on":"2026-10-09","outcome":"QA demonstration completed","participants":"QA participant names","status":"Reviewed"}';
 begin perform public.save_project_training(l,1,p,reviewed,'QA forbidden self review');raise exception 'Manager review allowed';exception when others then if sqlerrm is distinct from 'Administrator reviews or archives training' then raise;end if;end;n:=n+1;
 perform public.save_project_training(l,1,p,reviewed||'{"status":"Draft"}','QA draft outcome');if not exists(select 1 from public.crm_project_training where id=l and version=2) then raise exception 'Draft revision mismatch';end if;n:=n+1;
 perform set_config('request.jwt.claim.sub',a::text,true);
 begin perform public.save_project_training(l,2,p,d||'{"status":"Reviewed"}','QA incomplete review');raise exception 'Incomplete review allowed';exception when others then if sqlerrm is distinct from 'Review requires facilitator, participants, completion date, outcome and evidence' then raise;end if;end;n:=n+1;
 begin perform public.save_project_training(l,2,p,reviewed||'{"status":"Archived"}','QA skipped review');raise exception 'Draft archive allowed';exception when others then if sqlerrm is distinct from 'Review training before archiving' then raise;end if;end;n:=n+1;
 perform public.save_project_training(l,2,p,reviewed,'QA admin review');if not exists(select 1 from public.crm_project_training_history where training_id=l and revision=3 and actor_id=a and before_training->'details'->>'status'='Draft' and after_training->'details'->>'status'='Reviewed') then raise exception 'Review evidence mismatch';end if;n:=n+1;
 perform set_config('request.jwt.claim.sub',m::text,true);begin perform public.save_project_training(l,3,p,d,'QA forbidden withdrawal');raise exception 'Manager withdrawal allowed';exception when others then if sqlerrm is distinct from 'Administrator must revise or withdraw training review' then raise;end if;end;n:=n+1;
 perform set_config('request.jwt.claim.sub',a::text,true);perform public.save_project_training(l,3,p,reviewed||'{"status":"Archived"}','QA archive reviewed training');if not exists(select 1 from public.crm_project_training where id=l and version=4 and details->>'status'='Archived') then raise exception 'Archive mismatch';end if;n:=n+1;
 begin perform public.save_project_training(l,4,p,d,'QA forbidden archive edit');raise exception 'Archive editable';exception when others then if sqlerrm is distinct from 'Archived training is immutable' then raise;end if;end;n:=n+1;
 begin update public.crm_project_training set version=99 where id=l;raise exception 'Direct mutation allowed';exception when insufficient_privilege then null;end;n:=n+1;
 begin delete from public.crm_project_training_history where training_id=l;raise exception 'History deletion allowed';exception when insufficient_privilege then null;end;n:=n+1;
 perform set_config('request.jwt.claim.sub',u::text,true);if exists(select 1 from public.crm_project_training where id=l) or exists(select 1 from public.crm_project_training_history where training_id=l) then raise exception 'Client read allowed';end if;n:=n+1;
 begin perform public.save_project_training(gen_random_uuid(),null,p,d,'QA forbidden client create');raise exception 'Client create allowed';exception when others then if sqlerrm is distinct from 'Assigned project manager access required' then raise;end if;end;n:=n+1;
 execute 'reset role';delete from public.project_assignments where project_id=p and technician_id=m;execute 'set local role authenticated';perform set_config('request.jwt.claim.sub',m::text,true);if exists(select 1 from public.crm_project_training where id=l) then raise exception 'Revoked manager read allowed';end if;n:=n+1;
 begin perform public.save_project_training(gen_random_uuid(),null,p,d,'QA forbidden revoked create');raise exception 'Revoked create allowed';exception when others then if sqlerrm is distinct from 'Assigned project manager access required' then raise;end if;end;n:=n+1;
 execute 'reset role';if has_function_privilege('anon','public.save_project_training(uuid,integer,uuid,jsonb,text)','EXECUTE') then raise exception 'Anonymous RPC allowed';end if;n:=n+1;
 perform set_config('qa.training_result',jsonb_build_object('passed',true,'assertions',n,'fixtures_rollback',true)::text,true);
end$$;
select current_setting('qa.training_result')::jsonb as qa_result;
rollback;
